const winston = require('/work/lib/winston');
let transport = new winston.transports.Console();
transport.level = 'debug';
let logger = winston.createLogger({level:'info', levels: winston.config.npm.levels, transports:[transport]});
setTimeout(() => {
  const pipes = logger._readableState.pipes;
  console.log('pip count', Array.isArray(pipes) ? pipes.length : (pipes ? 1 : 0));
  if (Array.isArray(pipes)) {
    console.log('pip0 level', pipes[0].level, 'pip0 name', pipes[0].name, 'pip0 is transport?', pipes[0] === transport, 'pip0.log length', pipes[0].log && pipes[0].log.length, 'pip0.log in proto?', 'log' in Object.getPrototypeOf(pipes[0]));
  }
  process.exit(0);
}, 50);
